def validate_call(name,args,allowed):
    if name not in allowed:return False
    if name=='read_failure':return set(args)=={'failure_id'} and args['failure_id'].startswith('F') and args['failure_id'][1:].isdigit()
    if name=='search_history':return set(args)=={'query'} and isinstance(args['query'],str) and len(args['query'])<=1000
    return False

